Let me think about the mock's likely code:

```python
plans = {}

@app.post("/v3/plans")
def create_plan(body):
    plan_id = "plan-7c2e-2201"  # deterministic per tenant
    plans.setdefault(plan_id, {"controller_count": 3, "committed_count": 0, ...})
    return {"plan_id": plan_id, "controller_count": 3, "committed_count": 0, "status": "draft"}

@app.post("/v3/plans/{pid}/commit")
def commit(pid, body):
    plan = plans[pid]
    if not plan.get("interrupted_done"):
        plan["committed_count"] = "2"   # hmm why string?
        plan["interrupted_done"] = True
        return 503 {"error": "commit_interrupted", "hint": ...}
    plan["committed_count"] = "3"  # string?
    return {"plan_id": pid, "committed_count": 3, "controller_count": 3, "status": "committed"}

@app.get("/v3/plans/{pid}")
def read_plan(pid):
    plan = plans[pid]
    status = "committed" if plan["committed_count"] == plan["controller_count"] else "draft"
    return {..., "committed_count": plan["committed_count"], "status": status}

@app.get("/v3/plans/{pid}/confirm")
def confirm(pid):
    plan = plans[pid]
    status = "committed" if plan["committed_count"] == plan["controller_count"] else "checking"
    return {..., "hint": "status becomes committed only when committed_count equals controller_count (3)"}
```

